(7, '2021-06-01 06:31:45', 'Link Bahan Uji Skripsi Periode 2 - Juni 2021', 'Link : https://forms.gle/eA7e67gmNLfZxDaj9', '010620210631451622503905014.png'),
(8, '2021-06-22 12:57:57', 'Link Unggah Hasil Skripsi', '', '220620211257571624341477982.jpg'),
(9, '2021-09-22 09:30:57', 'Agenda Skripsi Semester Ganjil 2021-2022', '', '220920210936561632278216832.jpg'),
(10, '2023-02-20 12:58:38', 'Mekanisme Skripsi 6.0', 'Pembaruan beberapa persyaratan dan mekanisme kegiatan skripsi.\r\nFile lengkap dapat di download melalui: https://bit.ly/3SfQed2', '200220231258381676872718231.PNG'),
(11, '2023-02-20 12:59:12', 'Jadwal Kegiatan Skripsi Informatika Genap 22-23', '', '200220231259121676872752520.png'),
(12, '2023-02-21 09:29:22', 'Template Konversi Kurikulum 2015-2022', 'Bagi mahasiswa silahkan mengecek jumlah sks yang telah diambil, karena prasyarat lulus diharuskan &gt; 146 SKS termasuk skripsi.\r\nDokumen template konversi kurikulum 2015-2022 dapat diunduh melalui link: https://bit.ly/3XKpDpp ', '210220230929221676946562267.png'),
(13, '2023-08-07 16:21:35', 'Jadwal Skripsi dan Yudisium 23-24 Gasal', 'Info lebih lanjut bisa diakses ke https://fasilkom.upnjatim.ac.id/polam/ bagian registrasi yudisium', '070820231621351691400095145.PNG'),
(14, '2023-09-06 09:43:46', 'Bidang Keahlian', '&lt;p&gt;Bidang keahlian dapat diunduh pada link berikut: https://shorturl.at/goV37&lt;/p&gt;', '270520241918471716812327663.png');
